// ------------------------------------------------------------
// PART A / PART B live MIDI state
// Updated from MIDI messages sent toward the SD-80.
// Cable 0 = PART A, Cable 1 = PART B.
// ------------------------------------------------------------
struct PartMidiState
{
    int midiChannel = -1;       // 1..16, -1 = unknown
    int bankMSB = -1;           // CC#0
    int bankLSB = -1;           // CC#32
    int program = -1;           // 0..127 MIDI Program Change value
    bool programReceived = false;
    bool bankMSBReceived = false;
    bool bankLSBReceived = false;

    // Live note monitor.  noteOn means at least one MIDI note is currently
    // held on this channel. lastNote is the most recently received Note On.
    bool activeNotes[128]{};
    bool noteOn = false;
    int lastNote = -1;

    // Frequently useful channel controllers.  Other CC messages are still
    // passed through to the SD-80; these are simply the values displayed
    // in the GUI.
    int ccVolume = -1;      // CC#7
    int ccPan = -1;         // CC#10
    int ccExpression = -1;  // CC#11
    int ccModulation = -1;  // CC#1
    int ccReverb = -1;      // CC#91
    int ccChorus = -1;      // CC#93

    int pitchBend = 0;
    bool pitchBendReceived = false;
};

// PART A = 0, PART B = 1
// Each PART keeps an independent state for MIDI channels 1..16.
static std::mutex g_partStateMutex;
static PartMidiState g_partState[2][16];

// The GUI shows one PART at a time.
static int g_selectedPart = 0;

// SD-80 instrument-name display mode.
