// ------------------------------------------------------------
// Start SD80VirtualMidi backend
// ------------------------------------------------------------

static PROCESS_INFORMATION g_backendProcess{};
static HANDLE g_backendStdinWrite = nullptr;


static bool StartBackendProcess()
{
    WCHAR modulePath[MAX_PATH]{};

    if (GetModuleFileNameW(
        nullptr,
        modulePath,
        MAX_PATH) == 0)
    {
        return false;
    }

    std::filesystem::path guiPath(modulePath);

    std::filesystem::path backendPath =
        guiPath.parent_path() /
        L"SD80VirtualMidi.exe";

    if (!std::filesystem::exists(backendPath))
    {
        MessageBoxW(
            nullptr,
            L"SD80VirtualMidi.exe が見つかりません。\n\n"
            L"GUIと同じフォルダーにあることを確認してください。",
            L"SD-80 BRIDGE",
            MB_OK | MB_ICONERROR);

        return false;
    }

    SECURITY_ATTRIBUTES sa{};

    sa.nLength =
        sizeof(SECURITY_ATTRIBUTES);

    sa.bInheritHandle = TRUE;

    sa.lpSecurityDescriptor = nullptr;

    HANDLE stdinRead = nullptr;
    HANDLE stdinWrite = nullptr;

    HANDLE stdoutRead = nullptr;
    HANDLE stdoutWrite = nullptr;


    if (!CreatePipe(
        &stdinRead,
        &stdinWrite,
        &sa,
        0))
    {
        MessageBoxW(
            nullptr,
            L"標準入力パイプの作成に失敗しました。",
            L"SD-80 BRIDGE",
            MB_OK | MB_ICONERROR);

        return false;
    }

    // GUI側が書き込むハンドルは子プロセスに継承させない。
    if (!SetHandleInformation(
        stdinWrite,
        HANDLE_FLAG_INHERIT,
        0))
    {
        CloseHandle(stdinRead);
        CloseHandle(stdinWrite);

        MessageBoxW(
            nullptr,
            L"標準入力パイプのハンドル設定に失敗しました。",
            L"SD-80 BRIDGE",
            MB_OK | MB_ICONERROR);

        return false;
    }


    if (!CreatePipe(
        &stdoutRead,
        &stdoutWrite,
        &sa,
        0))

    {
        MessageBoxW(
            nullptr,
            L"バックエンド出力パイプの作成に失敗しました。",
            L"SD-80 BRIDGE",
            MB_OK | MB_ICONERROR);

        return false;
    }

    // The GUI must own the read side.
    SetHandleInformation(
        stdoutRead,
        HANDLE_FLAG_INHERIT,
        0);


    DWORD stdinFlags = 0;
    GetHandleInformation(stdinRead, &stdinFlags);

    DWORD stdoutFlags = 0;
    GetHandleInformation(stdoutWrite, &stdoutFlags);

    std::wcerr
        << L"[DEBUG] stdinRead inherit = "


        << ((stdinFlags & HANDLE_FLAG_INHERIT) ? L"YES" : L"NO")
        << std::endl;

    std::wcerr
        << L"[DEBUG] stdoutWrite inherit = "
        << ((stdoutFlags & HANDLE_FLAG_INHERIT) ? L"YES" : L"NO")
        << std::endl;


    STARTUPINFOW si{};

    si.cb =
        sizeof(STARTUPINFOW);

    si.dwFlags =
        STARTF_USESTDHANDLES;

    si.hStdInput =
        stdinRead;


    si.hStdOutput =
        stdoutWrite;

    si.hStdError =
        stdoutWrite;

    PROCESS_INFORMATION pi{};

    std::wstring commandLine =
        L"\"" +
        backendPath.wstring() +
        L"\"";

    BOOL result =
        CreateProcessW(
            nullptr,
            commandLine.data(),
            nullptr,
            nullptr,
            TRUE,
            CREATE_NO_WINDOW,
            nullptr,
            backendPath.parent_path().c_str(),
            &si,
            &pi);

    CloseHandle(stdinRead);
    CloseHandle(stdoutWrite);

    if (!result)
    {
        CloseHandle(stdoutRead);
        CloseHandle(stdinWrite);

        WCHAR message[256]{};

        swprintf_s(
            message,
            L"SD80VirtualMidi.exe の起動に失敗しました。\n\n"
            L"エラーコード: %lu",
            GetLastError());

        MessageBoxW(
            nullptr,
            message,
            L"SD-80 BRIDGE",
            MB_OK | MB_ICONERROR);

        return false;
    }

    g_backendStdinWrite = stdinWrite;

    g_backendStdoutRead =
        stdoutRead;

    g_backendProcess =
        pi;
    g_backendStarted = true;
    g_virtualMidiReady = false;
    g_sd80BackendReady = false;

    // Start output reader.
    g_backendReaderRunning = true;

    g_backendReaderThread =
        std::thread(
            BackendReaderThreadProc,
            FindWindowW(
                szWindowClass,
                L"SD-80 BRIDGE"));

    return true;
}


