static HFONT CreateUIFont(int size, int weight, const wchar_t* face = L"Segoe UI")
{
    return CreateFontW(
        -size,
        0,
        0,
        0,
        weight,
        FALSE,
        FALSE,
        FALSE,
        DEFAULT_CHARSET,
        OUT_DEFAULT_PRECIS,
        CLIP_DEFAULT_PRECIS,
        CLEARTYPE_QUALITY,
        DEFAULT_PITCH | FF_DONTCARE,
        face);
}

static void FillSolid(HDC hdc, const RECT& rc, COLORREF color)
{
    HBRUSH brush = CreateSolidBrush(color);
    FillRect(hdc, &rc, brush);
    DeleteObject(brush);
}

static void DrawTextSimple(
    HDC hdc,
    const wchar_t* text,
    RECT rc,
    HFONT font,
    COLORREF color,
    UINT format)
{
    // LCD status text must NEVER paint its own background.
    // The pale-blue LCD surface belongs exclusively to the embedded
    // header bitmap.  Save/restore the DC state so no caller can
    // accidentally change this behavior.
    HFONT oldFont = (HFONT)SelectObject(hdc, font);
    const int oldBkMode = SetBkMode(hdc, TRANSPARENT);
    const COLORREF oldTextColor = SetTextColor(hdc, color);

    DrawTextW(
        hdc,
        text,
        -1,
        &rc,
        format);

    SetTextColor(hdc, oldTextColor);
    SetBkMode(hdc, oldBkMode);
    SelectObject(hdc, oldFont);
}

